(() => {
  // src/js/form/api.js
  var schemaUrl = "/api/sections";
  var schema = async () => {
    const res = await fetch(schemaUrl);
    const data = await res.json();
    return data;
  };

  // src/js/html/maker.js
  function textarea(field) {
    const textarea2 = document.createElement("textarea");
    textarea2.id = field.id;
    textarea2.name = field.id;
    textarea2.placeholder = field.placeholder;
    return textarea2;
  }
  function select(field) {
    const select2 = document.createElement("select");
    select2.id = field.id;
    select2.name = field.id;
    const defOp = document.createElement("option");
    defOp.value = "";
    defOp.textContent = "-- Selecciona --";
    defOp.disabled = true;
    defOp.selected = true;
    defOp.hidden = true;
    select2.appendChild(defOp);
    field.options.forEach((op) => {
      const option = document.createElement("option");
      option.value = op;
      option.textContent = op;
      select2.appendChild(option);
    });
    return select2;
  }
  function text(field) {
    const text2 = document.createElement("input");
    text2.type = "text";
    if (field.placeholder) text2.placeholder = field.placeholder;
    text2.name = field.id;
    text2.id = field.id;
    return text2;
  }
  function radios(field) {
    const contanier = document.createElement("div");
    field.options.forEach((op) => {
      const optionId = `${field.id}_${op}`;
      const div = document.createElement("div");
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.type = "radio";
      input.id = optionId;
      input.name = field.id;
      input.value = op;
      div.appendChild(input);
      label.setAttribute("for", optionId);
      label.textContent = op;
      div.appendChild(label);
      div.style = "display: flex; gap: 10px;";
      contanier.appendChild(div);
    });
    return contanier;
  }
  function pills(field) {
    const fragment = document.createDocumentFragment();
    const pillsDiv = document.createElement("div");
    const input = document.createElement("input");
    const note = document.createElement("p");
    note.textContent = "Separa cada elemento con una coma ( , )";
    pillsDiv.setAttribute("pills-container", "");
    pillsDiv.id = `${field.id}_pills`;
    input.type = "text";
    input.id = field.id;
    input.name = field.id;
    input.placeholder = field.placeholder;
    fragment.appendChild(note);
    fragment.appendChild(pillsDiv);
    fragment.appendChild(input);
    return fragment;
  }
  function dynCL(field) {
    const fragment = document.createDocumentFragment();
    const optionsDiv = document.createElement("div");
    optionsDiv.id = field.id;
    optionsDiv.setAttribute("dynCL-options", "");
    fragment.appendChild(optionsDiv);
    return fragment;
  }

  // src/js/form/renderForm.js
  var formContainer = document.querySelector("[data-form-root]");
  function renderInput(field) {
    switch (field.type) {
      case "textarea":
        return textarea(field);
      case "select":
        return select(field);
      case "radio":
        return radios(field);
      case "pills":
        return pills(field);
      case "dynamicChecklist":
        return dynCL(field);
      default:
        return text(field);
    }
  }
  function labelHasInput(type) {
    return type === "radio" || type === "dynamicChecklist";
  }
  function renderField(field, fieldCounter) {
    const div = document.createElement("div");
    const label = document.createElement("label");
    label.textContent = `${fieldCounter}.- ${field.label}`;
    if (field.required === true) label.textContent += " *";
    if (!labelHasInput(field.type)) label.htmlFor = field.id;
    div.appendChild(label);
    const input = renderInput(field);
    if (field.required === true) input.required = true;
    if ("minLength" in field) input.setAttribute("min", field.minLength);
    if ("maxLength" in field) input.setAttribute("max", field.maxLength);
    div.appendChild(input);
    fieldCounter++;
    return div;
  }
  function section(sId, sec) {
    const title = sec.title;
    const fields = sec.fields;
    const fieldset = document.createElement("fieldset");
    fieldset.id = sId;
    const legend = document.createElement("legend");
    legend.textContent = title;
    fieldset.appendChild(legend);
    let fieldCounter = 1;
    fields.forEach((field) => {
      const input = renderField(field, fieldCounter);
      fieldset.appendChild(input);
      fieldCounter++;
    });
    formContainer.appendChild(fieldset);
  }
  function submit() {
    const submitBtn = document.createElement("input");
    submitBtn.type = "submit";
    submitBtn.value = "Enviar";
    formContainer.appendChild(submitBtn);
  }

  // src/js/form/initForm.js
  async function formInit() {
    const sections = await schema();
    Object.entries(sections).forEach(async (section2) => {
      const sId = section2[0];
      const sec = section2[1];
      if (sId === "identificacion") return;
      section(sId, sec);
    });
    submit();
  }

  // src/js/app.js
  formInit();
})();
